"""Buduje web/index.html z source.html (kod dziennika) + nagłówek PWA i most do serwera."""
from pathlib import Path
H = Path(__file__).parent
src = (H / "source.html").read_text(encoding="utf-8")
head = '''<!doctype html><html lang="pl"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="theme-color" content="#08090A">
<link rel="manifest" href="/manifest.webmanifest">
<link rel="apple-touch-icon" href="/ikona-180.png">
<meta name="apple-mobile-web-app-capable" content="yes">
<meta name="mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-title" content="Dziennik">
<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">
<style>html{padding-top:env(safe-area-inset-top,0px)}body{margin:0}[hidden]{display:none!important}</style>
<script src="/shim.js"></script>
'''
out = head + src.replace("<title>Dziennik treningowy</title>", "<title>Dziennik treningowy</title></head><body><div id=\"dz-splash\" style=\"position:fixed;inset:0;z-index:10000;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:22px;background:radial-gradient(60% 40% at 50% 0%,rgba(120,98,255,.22),transparent 70%),#08090A;transition:opacity .35s ease\"><div class=\"dzbb\"><i class=\"dzpl l2\"></i><i class=\"dzpl l1\"></i><b class=\"dzbar\"></b><i class=\"dzpl r1\"></i><i class=\"dzpl r2\"></i></div><div class=\"dzsh\"></div><div class=\"dzw\"><span style=\"animation-delay:0.45s,0.45s\">D</span><span style=\"animation-delay:0.51s,0.51s\">Z</span><span style=\"animation-delay:0.57s,0.57s\">I</span><span style=\"animation-delay:0.63s,0.63s\">E</span><span style=\"animation-delay:0.69s,0.69s\">N</span><span style=\"animation-delay:0.75s,0.75s\">N</span><span style=\"animation-delay:0.81s,0.81s\">I</span><span style=\"animation-delay:0.87s,0.87s\">K</span></div><div class=\"dzsub\">treningowy</div><style>#dz-splash{--c:2.6s}.dzbb{position:relative;width:200px;height:70px;animation:dzlift var(--c) cubic-bezier(.5,0,.3,1) infinite}.dzbar{position:absolute;left:0;right:0;top:32px;height:6px;border-radius:3px;background:linear-gradient(90deg,#8A8F9C,#E6E8EE,#8A8F9C)}.dzpl{position:absolute;top:8px;width:14px;height:54px;border-radius:5px;background:linear-gradient(180deg,#BDB0FF,#7E69F5);box-shadow:0 0 18px -4px #9E8CFC}.dzpl.l1{left:38px;animation:dzinL var(--c) infinite}.dzpl.l2{left:22px;height:44px;top:13px;animation:dzinL var(--c) .1s infinite}.dzpl.r1{right:38px;animation:dzinR var(--c) infinite}.dzpl.r2{right:22px;height:44px;top:13px;animation:dzinR var(--c) .1s infinite}@keyframes dzinL{0%{transform:translateX(-90px);opacity:0}18%,88%{transform:none;opacity:1}100%{opacity:0}}@keyframes dzinR{0%{transform:translateX(90px);opacity:0}18%,88%{transform:none;opacity:1}100%{opacity:0}}@keyframes dzlift{0%,30%{transform:translateY(16px)}52%{transform:translateY(-22px)}58%{transform:translateY(-17px)}80%,100%{transform:translateY(16px)}}.dzsh{width:150px;height:10px;border-radius:50%;background:rgba(126,105,245,.35);filter:blur(8px);margin-top:-14px;animation:dzshd var(--c) cubic-bezier(.5,0,.3,1) infinite}@keyframes dzshd{0%,30%,80%,100%{transform:scale(1);opacity:.8}52%{transform:scale(.55);opacity:.25}}.dzw{font:800 34px/1 -apple-system,system-ui,sans-serif;letter-spacing:.12em;margin-top:4px}.dzw span{display:inline-block;background:linear-gradient(100deg,#7E69F5 25%,#fff 50%,#7E69F5 75%);background-size:300% 100%;-webkit-background-clip:text;background-clip:text;color:transparent;animation:dzup var(--c) cubic-bezier(.34,1.56,.64,1) infinite,dzshine var(--c) linear infinite}@keyframes dzup{0%{transform:translateY(22px);opacity:0}8%{transform:none;opacity:1}22%{transform:translateY(-8px)}30%,75%{transform:none;opacity:1}90%,100%{transform:translateY(0);opacity:0}}@keyframes dzshine{0%,10%{background-position:100% 0}35%,100%{background-position:0 0}}.dzsub{font:600 13px/1 -apple-system,system-ui,sans-serif;letter-spacing:.35em;text-transform:uppercase;color:#98A2B3;margin-top:-12px;animation:dzfade var(--c) infinite}@keyframes dzfade{0%,25%{opacity:0}40%,80%{opacity:1}95%,100%{opacity:0}}@media (prefers-reduced-motion:reduce){#dz-splash *{animation:none!important}}</style></div>", 1) + "\n</body></html>\n"
(H / "web" / "index.html").write_text(out, encoding="utf-8")
print("index.html", len(out))
